require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/Upload.php';require_once __DIR__.'/../lib/DocsRepository.php';Auth::requirePermission('docs.manage','edit');$pageTitle='ثبت مستند آموزشی';$adminExtraStylesheets=['/assets/css/workforce.css'];$adminExtraScripts=['/assets/js/workforce.js'];$id=(int)($_GET['id']??$_POST['id']??0);$doc=$id?Database::fetch('SELECT * FROM docs_articles WHERE id=?',[$id]):null;if($id&&!$doc){http_response_code(404);exit('مستند پیدا نشد.');}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/docs.php');}try{$title=trim((string)($_POST['title']??''));if($title==='')throw new InvalidArgumentException('عنوان مستند الزامی است.');$content=DocsAccessService::sanitize($_POST['content']??'');if(trim(strip_tags($content))==='')throw new InvalidArgumentException('متن مستند الزامی است.');$slug=trim((string)($_POST['slug']??''));if($slug==='')$slug='doc-'.bin2hex(random_bytes(6));if(!preg_match('/^[a-z0-9_-]+$/i',$slug))throw new InvalidArgumentException('نامک باید انگلیسی باشد.');if(Database::fetch('SELECT id FROM docs_articles WHERE slug=? AND id<>?',[$slug,$id]))throw new InvalidArgumentException('نامک تکراری است.');$scope=in_array($_POST['visibility_scope']??'',['all','units','roles','users'],true)?$_POST['visibility_scope']:'all';$roles=array_values(array_unique(array_map('intval',$_POST['allowed_roles']??[])));$units=array_values(array_unique(array_map('intval',$_POST['allowed_units']??[])));$users=array_values(array_unique(array_map('intval',$_POST['allowed_users']??[])));if($scope==='roles'&&!$roles||$scope==='units'&&!$units||$scope==='users'&&!$users)throw new InvalidArgumentException('برای سطح دسترسی انتخاب‌شده حداقل یک مورد تعیین کنید.');$attachmentPath=$doc['attachment_path']??null;$attachmentName=$doc['attachment_name']??null;$attachmentMime=$doc['attachment_mime']??null;if(($_FILES['attachment']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$saved=Upload::save($_FILES['attachment'],'uploads/docs',['pdf','doc','docx','xls','xlsx','jpg','jpeg','png','webp','txt'],15*1024*1024);if(!$saved['ok'])throw new InvalidArgumentException($saved['error']);$attachmentPath=$saved['file_path'];$attachmentName=substr($saved['original_name'],0,255);$attachmentMime=$saved['mime_type'];}$data=[(int)($_POST['category_id']??0)?:null,$title,$slug,trim((string)($_POST['summary']??'')),$content,$attachmentPath,$attachmentName,$attachmentMime,$scope,json_encode($roles),json_encode($units),json_encode($users),isset($_POST['require_read_confirmation'])?1:0,isset($_POST['active'])?1:0];if($id)Database::execute('UPDATE docs_articles SET category_id=?,title=?,slug=?,summary=?,content=?,attachment_path=?,attachment_name=?,attachment_mime=?,visibility_scope=?,allowed_roles_json=?,allowed_units_json=?,allowed_users_json=?,require_read_confirmation=?,active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else{Database::execute('INSERT INTO docs_articles(category_id,title,slug,summary,content,attachment_path,attachment_name,attachment_mime,visibility_scope,allowed_roles_json,allowed_units_json,allowed_users_json,require_read_confirmation,active,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())',[...$data,(int)Auth::user()['id']]);$id=(int)Database::lastInsertId();}Auth::log((int)Auth::user()['id'],$doc?'docs_article_updated':'docs_article_created','docs_articles',$id);flash('مستند با موفقیت ذخیره شد.');redirect('/admin/docs.php');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Docs article: '.$e->getMessage());flash('ذخیره مستند انجام نشد.','danger');}redirect('/admin/docs-edit.php'.($id?'?id='.$id:''));}
