<div class="workforce-head"><div><h1><?=$doc?'ویرایش مستند':'مستند جدید'?></h1><p>محتوا، فایل و مخاطبان مجاز را مشخص کنید.</p></div><a class="btn" href="/admin/docs.php">بازگشت</a></div><form method="post" enctype="multipart/form-data" data-doc-editor><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e($doc['id']??'')?>"><div class="workforce-grid"><section class="card"><div class="compact-grid"><label class="form-field"><span>عنوان</span><input name="title" value="<?=e($doc['title']??'')?>" required></label><label class="form-field"><span>نامک انگلیسی</span><input name="slug" dir="ltr" value="<?=e($doc['slug']??'')?>"></label><label class="form-field"><span>دسته‌بندی</span><select name="category_id"><option value="">بدون دسته</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=(int)($doc['category_id']??0)===(int)$c['id']?'selected':''?>><?=e($c['title'])?></option><?php endforeach?></select></label></div><label class="form-field"><span>خلاصه</span><textarea name="summary" rows="3"><?=e($doc['summary']??'')?></textarea></label><textarea hidden name="content" data-editor-input><?=e($doc['content']??'')?></textarea><div class="doc-toolbar"><button type="button" data-command="bold"><b>ضخیم</b></button><button type="button" data-command="italic"><i>مورب</i></button><button type="button" data-command="underline"><u>زیرخط</u></button><button type="button" data-command="insertUnorderedList">فهرست</button><button type="button" data-command="justifyRight">راست‌چین</button><button type="button" data-command="justifyCenter">وسط‌چین</button></div><div class="doc-editor doc-content" contenteditable="true" data-editor-surface><?=$doc?DocsAccessService::sanitize($doc['content']):'<p>متن مستند را اینجا بنویسید.</p>'?></div></section><aside class="card"><label class="form-field"><span>سطح دسترسی</span><select name="visibility_scope"><option value="all" <?=($doc['visibility_scope']??'all')==='all'?'selected':''?>>همه کاربران</option><option value="units" <?=($doc['visibility_scope']??'')==='units'?'selected':''?>>واحدهای منتخب</option><option value="roles" <?=($doc['visibility_scope']??'')==='roles'?'selected':''?>>نقش‌های منتخب</option><option value="users" <?=($doc['visibility_scope']??'')==='users'?'selected':''?>>کاربران منتخب</option></select></label><label class="form-field"><span>واحدها</span><select name="allowed_units[]" multiple size="5"><?php foreach($units as $u):?><option value="<?=$u['id']?>" <?=in_array((int)$u['id'],$selectedUnits,true)?'selected':''?>><?=e($u['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>نقش‌ها</span><select name="allowed_roles[]" multiple size="5"><?php foreach($roles as $r):?><option value="<?=$r['id']?>" <?=in_array((int)$r['id'],$selectedRoles,true)?'selected':''?>><?=e($r['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>کاربران</span><select name="allowed_users[]" multiple size="6"><?php foreach($users as $u):?><option value="<?=$u['id']?>" <?=in_array((int)$u['id'],$selectedUsers,true)?'selected':''?>><?=e($u['name'].' — '.($u['employee_no']?:'بدون شماره'))?></option><?php endforeach?></select></label><label class="form-field"><span>پیوست (حداکثر ۱۵MB)</span><input type="file" name="attachment" accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.webp,.txt"><?php if($doc&&$doc['attachment_name']):?><small>فایل فعلی: <?=e($doc['attachment_name'])?></small><?php endif?></label><label class="checkbox-item"><input type="checkbox" name="require_read_confirmation" <?=!empty($doc['require_read_confirmation'])?'checked':''?>> تایید مطالعه الزامی است</label><label class="checkbox-item"><input type="checkbox" name="active" <?=!isset($doc['active'])||(int)$doc['active']?'checked':''?>> فعال</label><button class="btn btn-primary">ذخیره مستند</button></aside></div></form><?php require __DIR__.'/../views/partials/admin-footer.php';?>
